import uploadPictures from "@/components/uploadPictures";
import OperationFloorModal from "@/components/hotpotModal";
export default {
  name: "c_one_pictrue",
  components: {
    uploadPictures: uploadPictures,
    OperationFloorModal: OperationFloorModal
  },
  props: {
    configObj: {
      type: Object
    },
    configNme: {
      type: String
    }
  },
  data: function data() {
    return {
      defaults: {},
      configData: {
        list: []
      },
      gridBtn: {
        xl: 4,
        lg: 8,
        md: 8,
        sm: 8,
        xs: 8
      },
      gridPic: {
        xl: 6,
        lg: 8,
        md: 12,
        sm: 12,
        xs: 12
      },
      modalPic: false,
      isChoice: "单选",
      imgAreaData: [] //热区数据
    };
  },
  watch: {
    configObj: {
      handler: function handler(nVal, oVal) {
        this.configData = nVal.picStyle;
        this.defaults = nVal;
        this.$set(this, 'imgAreaData', nVal.picStyle.list);
      },
      deep: true
    }
  },
  mounted: function mounted() {
    var _this = this;
    this.$nextTick(function () {
      _this.defaults = _this.configObj;
      _this.configData = _this.configObj[_this.configNme];
      _this.imgAreaData = _this.configObj.picStyle.list;
    });
  },
  methods: {
    bindDelete: function bindDelete() {
      this.configData.url = "";
    },
    // 点击图文封面
    modalPicTap: function modalPicTap(title) {
      this.modalPic = true;
    },
    // 获取图片信息
    getPic: function getPic(pc) {
      var _this2 = this;
      this.$nextTick(function () {
        _this2.configData.url = pc.att_dir;
        _this2.configData.list = [];
        _this2.imgAreaData = [];
        _this2.modalPic = false;
      });
    },
    openFloorModal: function openFloorModal() {
      // 如果配置数据中有url，则显示热点图对话框
      if (this.configData.url) this.$refs.hotpot.dialogVisible = true;
    },
    /**
     * 处理区域数据
     * @param {Object} areaData - 区域数据对象
     */
    handleAreaData: function handleAreaData(areaData) {
      // 打印保存的数据
      this.configData.list = areaData;
      console.log(this.configData.list, 'list');
    }
  }
};
